// types.go
package main

// Severity represents the severity level of a configuration finding.
type Severity int

const (
	// SevWarning is a recommendation, tuning hint, or low-impact issue.
	SevWarning Severity = iota
	// SevError is a configuration error that likely breaks authentication.
	SevError
	// SevCritical is a severe misconfiguration that reliably breaks AD integration.
	SevCritical
)

// ConfigFinding is a structured, provenance-aware diagnostic generated by the
// sssd.conf/AD configuration validator and the cross-source correlation engine.
// It carries the offending source line so the UI can render drill-down evidence.
//
// Evidence contract: every finding built through addConfigFinding (or
// addConfigFindingEx) must carry RuleID, Confidence and DocRef. RuleID names
// the check that fired ("catalog:unknown-option", "domain:missing-id-provider",
// ...), Confidence records which ground-truth layer decided ("api", "man",
// "curated", "heuristic", "log"), and DocRef points at the man page or source
// file backing the claim. configFindingContractTest enforces the contract so a
// false positive is always traceable to the rule that generated it.
type ConfigFinding struct {
	Severity   Severity `json:"severity"`    // SevWarning / SevError / SevCritical
	Category   string   `json:"category"`    // e.g. "ad_server", "krb5_realm", "dns", "join"
	Message    string   `json:"message"`     // human-readable, actionable text
	SourcePath string   `json:"source_path"` // e.g. "sssd.conf", "krb5.conf", "resolv.conf"
	SourceKey  string   `json:"source_key"`  // logical key, e.g. "domain/EXAMPLE.COM.ad_server"
	SourceLine int      `json:"source_line"` // 1-based line number in SourcePath (0 = unknown)
	Evidence   string   `json:"evidence"`    // the offending config line text (PII-scrubbable)
	RuleID     string   `json:"rule_id"`     // stable rule identifier, e.g. "catalog:unknown-option"
	Confidence string   `json:"confidence"`  // "api" | "man" | "curated" | "heuristic" | "log"
	DocRef     string   `json:"doc_ref"`     // backing man page, e.g. "sssd-ldap(5)"
}

// SSSDLogError holds the human-readable description and samples of the actual log lines
type SSSDLogError struct {
	Description string   `json:"description"`
	Examples    []string `json:"examples"`
}

// TIDArticle represents a dynamically loaded Knowledge Base article.
//
// Evidence holds the log lines that triggered the match and IS shipped in the
// report: "which line matched?" is the question that turns a TID link into a
// diagnosis. It used to be tagged `json:"-"`, which is why the "Evidence
// Found" block in the GUI could never render. The lines are ordinary log
// excerpts, and anonymizeReport scrubs them exactly like
// SSSDLogError.Examples and TimelineEvent.RawLog.
type TIDArticle struct {
	TIDID          string   `json:"tid_id"`
	Title          string   `json:"title"`
	URL            string   `json:"url"`
	Description    string   `json:"description"`
	LogPatterns    []string `json:"log_patterns"`
	ConfigPatterns []string `json:"config_patterns"`
	Evidence       []string `json:"evidence,omitempty"` // Log lines that triggered the match

	// Fields from the kbscraper JSON schema (raw scraped SUSE KB articles).
	// These are ingestion-only: they carry the article content but do not
	// participate in pattern matching.
	KbID           string `json:"kb_id"`
	PlainText      string `json:"plain_text"`
	Situation      string `json:"situation"`
	Resolution     string `json:"resolution"`
	Cause          string `json:"cause"`
	Environment    string `json:"environment"`
	Created        string `json:"created"`
	Changed        string `json:"changed"`
	AdditionalInfo string `json:"additional_information"`

	// Conditions is the alternate (nested) curated schema: patterns live
	// under "conditions" instead of at the top level. normalizeTIDArticle
	// promotes them into LogPatterns/ConfigPatterns.
	Conditions *TIDConditions `json:"conditions,omitempty"`
}

// TIDConditions models the nested "conditions" object of the alternate
// curated KB schema.
type TIDConditions struct {
	LogPatterns    []string `json:"log_patterns"`
	ConfigPatterns []string `json:"config_patterns"`
	MinSSSDVersion string   `json:"min_sssd_version"`
}

// ExecutiveSummary is the triage block rendered at the top of every report:
// an overall health score, the finding counts per severity, and the inferred
// dominant root-cause category with a one-line headline.
type ExecutiveSummary struct {
	HealthScore     int    `json:"health_score"`    // 0-100 (100 = clean)
	CriticalCount   int    `json:"critical_count"`  // SevCritical config findings
	ErrorCount      int    `json:"error_count"`     // SevError config findings
	WarningCount    int    `json:"warning_count"`   // SevWarning findings + warnings
	ProblemCount    int    `json:"problem_count"`   // actionable problem strings
	LogErrorCount   int    `json:"log_error_count"` // distinct log error patterns found
	TopCategory     string `json:"top_category"`    // dominant finding category, e.g. "krb5_realm"
	TopCategoryHits int    `json:"top_category_hits"`
	Headline        string `json:"headline"` // one-line triage statement
}

// ReportData holds the results of our analysis
type ReportData struct {
	AppVersion    string `json:"app_version"`
	Timestamp     string `json:"timestamp"`
	SupportCaseID string `json:"support_case_id"`
	KernelVersion string `json:"kernel_version"`
	SLESRlease    string `json:"sles_release"`
	SCCStatus     string `json:"scc_status"`

	// Executive summary computed after all analysis phases (see analysis_scoring.go)
	Summary ExecutiveSummary `json:"summary"`

	// Virtualization & Hardware
	HardwareManufacturer string `json:"hardware_manufacturer"`
	HardwareModel        string `json:"hardware_model"`
	Hypervisor           string `json:"hypervisor"`
	VirtualIdentity      string `json:"virtual_identity"`
	MACType              string `json:"mac_type"`

	// Base Services
	SssdInstalled   bool     `json:"sssd_installed"`
	SssdConfigFound bool     `json:"sssd_config_found"`
	SssdService     string   `json:"sssd_service"`
	WinbindService  string   `json:"winbind_service"`
	NscdStatus      string   `json:"nscd_status"`
	NscdCaching     []string `json:"nscd_caching"`
	SSSDPackages    []string `json:"sssd_packages"`

	// Authentication Details
	NsswitchValid     bool     `json:"nsswitch_valid"`
	PamSssInstalled   bool     `json:"pam_sss_installed"`
	PamGDPRRestricted bool     `json:"pam_gdpr_restricted"`
	HostsIssues       []string `json:"hosts_issues"`
	HostsFileStatus   string   `json:"hosts_file_status"` // present / missing_on_host / not_collected / malformed
	Nameservers       []string `json:"nameservers"`
	SearchDomain      string   `json:"search_domain"`
	TimeService       string   `json:"time_service"`
	KerberosRealm     string   `json:"kerberos_realm"`
	KeytabFound       bool     `json:"keytab_found"`

	// SSSD Deep AD Configs
	ADProviderMode bool   `json:"ad_provider_mode"`
	EnumerateIssue bool   `json:"enumerate_issue"`
	UseFQDNSet     bool   `json:"use_fqdn_set"`
	AdDomain       string `json:"ad_domain"` // canonical (lowercased) AD domain from sssd.conf ad_domain
	Hostname       string `json:"hostname"`  // hostname/FQDN captured from basic-environment.txt

	// Structured, provenance-aware configuration findings (AD validator + correlation)
	ConfigFindings []ConfigFinding `json:"config_findings"`

	// CatalogProvenance records which offline SSSD option catalog validated
	// sssd.conf, so the report always states the documentation release its
	// configuration claims are based on.
	CatalogProvenance string `json:"catalog_provenance,omitempty"`

	// Diagnostics collects non-fatal definition-loading problems (skipped
	// YAML rules, malformed external KB articles). Fail-safe loaders drop
	// bad input; this slice is how the drop becomes visible to users.
	Diagnostics []Diagnostic `json:"diagnostics,omitempty"`

	// Log Analysis & Problems
	SSSDLogErrors     []SSSDLogError `json:"sssd_log_errors"`
	SSSDConfigSnippet string         `json:"sssd_config_snippet"`
	MACDenialExamples []string       `json:"mac_denial_examples"`

	Problems    []string        `json:"problems"`
	Warnings    []string        `json:"warnings"`
	MatchedTIDs []TIDArticle    `json:"matched_tids"`
	Timeline    []TimelineEvent `json:"timeline"`

	// Phase 3: advanced correlation output
	TemporalClusters []TemporalCluster `json:"temporal_clusters,omitempty"`
	KBSuggestions    []KBSuggestion    `json:"kb_suggestions,omitempty"`

	// Phase 4: interactive correlation graph (built after PII scrubbing)
	Graph CorrelationGraph `json:"graph"`
}

// Diagnostic records a non-fatal problem encountered while loading
// analysis definitions (YAML rules, external KB articles): the loader skips
// bad input fail-safe, but the skip must never be silent — every skipped
// file or rule is reported here with its file, line and a human-readable
// message so the GUI, the CLI and the JSON export can surface it.
type Diagnostic struct {
	File     string   `json:"file"`           // path of the offending definition file
	Line     int      `json:"line,omitempty"` // 1-based line when known
	Message  string   `json:"message"`        // human-readable explanation
	Severity Severity `json:"severity"`       // SevWarning: analysis continued without it
}

// AddDiagnostics appends diagnostics to the report, dropping exact
// duplicates. Loaders can run more than once per analysis (rules and the KB
// corpus are re-read per phase) and the same file must not be reported twice.
func (r *ReportData) AddDiagnostics(diags []Diagnostic) {
	for _, d := range diags {
		dup := false
		for _, e := range r.Diagnostics {
			if e.File == d.File && e.Line == d.Line && e.Message == d.Message {
				dup = true
				break
			}
		}
		if !dup {
			r.Diagnostics = append(r.Diagnostics, d)
		}
	}
}

// TimelineEvent represents a single chronological log occurrence.
//
// Occurrences is the number of times this diagnostic event was observed
// (bounded timeline aggregation, see analysis_timeline.go): the row keeps
// the FIRST timestamp/sample plus a count instead of one row per repeat, so
// huge retry-loop logs stay cheap while burst consumers can still weight
// by volume. Samples holds up to maxTimelineSamples distinct raw-log lines
// for drill-down (the first sample duplicates RawLog).
type TimelineEvent struct {
	Timestamp   string   `json:"timestamp"`
	Message     string   `json:"message"`
	RawLog      string   `json:"raw_log"`
	Occurrences int      `json:"occurrences,omitempty"`
	Samples     []string `json:"samples,omitempty"`
}

// TemporalCluster is a burst of the same diagnostic event inside a bounded
// time window (sliding-window co-occurrence). Repeated occurrences of the
// same error within seconds are the fingerprint of retry loops, timeouts and
// fail-over flapping; a single occurrence is usually noise.
type TemporalCluster struct {
	Description  string `json:"description"`  // the event description
	EventCount   int    `json:"event_count"`  // occurrences inside the window
	WindowStart  string `json:"window_start"` // normalized first occurrence
	WindowEnd    string `json:"window_end"`   // normalized last occurrence
	SampleRawLog string `json:"sample_raw_log"`
}

// KBSuggestion is a fuzzy (TF-IDF cosine similarity) match between an
// unmatched log line and a Knowledge Base article. Suggestions are ranked
// and only produced above a confidence threshold.
type KBSuggestion struct {
	TIDID      string  `json:"tid_id"`
	Title      string  `json:"title"`
	URL        string  `json:"url"`
	Score      float64 `json:"score"` // 0..1 cosine similarity
	SampleLine string  `json:"sample_line"`
}

// ============================================================================
// Correlation Graph Types (P5 / P9)
// ============================================================================

// GraphNodeKind distinguishes the three layers of the correlation graph.
type GraphNodeKind string

const (
	KindEntity  GraphNodeKind = "entity"
	KindFinding GraphNodeKind = "finding"
	KindSource  GraphNodeKind = "source"
)

// GraphEntity represents an extracted identity/state value from the report
// (AD domain, Kerberos realm, hostname, DNS search domain, ad_server,
// keytab principal, GPO) — the "nouns" of the diagnosis.
type GraphEntity struct {
	ID         string   `json:"id"`    // "entity:domain:example.com"
	Kind       string   `json:"kind"`  // "domain"|"realm"|"hostname"|"dns"|"ad_server"|"keytab"|"gpo"
	Label      string   `json:"label"` // human-readable (PII-scrubbed)
	Value      string   `json:"value,omitempty"`
	Severity   Severity `json:"severity"` // max severity of any finding touching this entity
	SourcePath string   `json:"source_path,omitempty"`
}

// GraphFindingNode is a diagnostic node: either a structured ConfigFinding
// or a temporal cluster / log-error summary. Findings are the "verbs" that
// connect entities to their evidence.
type GraphFindingNode struct {
	ID         string   `json:"id"` // "finding:<hash>"
	Category   string   `json:"category"`
	Message    string   `json:"message"`
	Severity   Severity `json:"severity"`
	SourcePath string   `json:"source_path,omitempty"`
	SourceKey  string   `json:"source_key,omitempty"`
	SourceLine int      `json:"source_line,omitempty"`
	Evidence   string   `json:"evidence,omitempty"`
	EventCount int      `json:"event_count,omitempty"`
	RuleID     string   `json:"rule_id,omitempty"`
	Confidence string   `json:"confidence,omitempty"`
	DocRef     string   `json:"doc_ref,omitempty"`
}

// GraphSourceNode pins a finding to the physical evidence in the supportconfig:
// the offending file path, line number and the raw line text.
type GraphSourceNode struct {
	ID         string `json:"id"` // "source:sssd.conf:42"
	SourcePath string `json:"source_path"`
	SourceLine int    `json:"source_line"`
	LineText   string `json:"line_text"`
}

// GraphEdge is a directed relationship between two graph nodes.
type GraphEdge struct {
	From string `json:"from"` // source node ID
	To   string `json:"to"`   // target node ID
	Kind string `json:"kind"` // "entity_to_finding"|"finding_to_source"
}

// CorrelationGraph is the serializable graph structure consumed by the
// interactive SVG renderer in the frontend. Built once per analysis by
// buildCorrelationGraph after PII anonymization.
type CorrelationGraph struct {
	Entities []GraphEntity      `json:"entities"`
	Findings []GraphFindingNode `json:"findings"`
	Sources  []GraphSourceNode  `json:"sources"`
	Edges    []GraphEdge        `json:"edges"`
}

// ComparisonReport holds the delta between two analyses (P5 — Diff Mode).
type ComparisonReport struct {
	A          ReportData `json:"a"`
	B          ReportData `json:"b"`
	Common     []string   `json:"common"`      // category+message keys present in both
	OnlyInA    []string   `json:"only_in_a"`   // keys unique to A
	OnlyInB    []string   `json:"only_in_b"`   // keys unique to B
	ScoreDelta int        `json:"score_delta"` // HealthScore(B) - HealthScore(A); positive means B is healthier
}
